def cantor_numbering(N: int) -> str:
    if N <= 0:
        raise ValueError("N must be a positive integer")

    diagonal = 1
    while N > diagonal:
        N -= diagonal
        diagonal += 1

    if diagonal % 2 == 0:
        numerator = diagonal - N + 1
        denominator = N
    else:
        numerator = N
        denominator = diagonal - N + 1

    return f"{numerator}/{denominator}"

def max_product(num_str: str, N: int, K: int) -> int:
    if N != len(num_str) or K < 0 or K > N - 1:
        raise ValueError("Invalid input")

    # Convert the number string into a list of integers for easier manipulation
    num_list = [int(digit) for digit in num_str]

    # If K is 0, we cannot insert any multiplication signs, so the result is the number itself
    if K == 0:
        return int("".join(map(str, num_list)))

    # Function to calculate the product of sublists
    def product(sublists):
        result = 1
        for sublist in sublists:
            result *= int("".join(map(str, sublist)))
        return result

    # If K is equal to N-1, we can insert a multiplication sign between every two digits
    if K == N - 1:
        return product([[num_list[i]] for i in range(N)])

    # To maximize the product, we should try to split the number into parts that are as large as possible
    # This can be achieved by placing multiplication signs between consecutive digits
    max_product_result = 0
    for i in range(1, K + 1):
        left_part = num_list[:i]
        remaining_parts = num_list[i:]
        product_result = product([left_part] + [remaining_parts[j:j+1] for j in range(0, len(remaining_parts), i)])
        if product_result > max_product_result:
            max_product_result = product_result

    return max_product_result

def max_product(num_str: str, N: int, K: int) -> int:
    # Edge case: if K is 0, no multiplication signs are inserted
    if K == 0:
        return int(num_str)

    # Edge case: if K is N-1, all characters become separate numbers
    if K == N - 1:
        return int(num_str[0]) * int(num_str[1]) * int(num_str[2])

    # Initialize the result to a very small number
    max_product = 0

    # Iterate through all possible positions to insert K multiplication signs
    for i in range(1, N):
        for j in range(i+1, N):
            for k in range(j+1, N):
                # Split the number string at the three positions
                parts = [num_str[:i], num_str[i:j], num_str[j:k], num_str[k:]]
                # Calculate the product of the split parts
                product = 1
                for part in parts:
                    product *= int(part)
                # Update the maximum product found
                max_product = max(max_product, product)

    return max_product

def max_product(num_str: str, N: int, K: int) -> int:
    if not num_str or N <= 0 or K < 0:
        raise ValueError("Invalid input")

    max_product = 0

    def dfs(index, product, k):
        nonlocal max_product
        if index == N:
            max_product = max(max_product, product)
            return

        if k == 0:
            dfs(N, product * int(num_str[index:]), 0)
            return

        for i in range(index + 1, N):
            dfs(i, product * int(num_str[index:i]), k - 1)

    dfs(0, 1, K)
    return max_product

def max_product(num_str: str, N: int, K: int) -> int:
    if not num_str or N <= 0 or K < 0 or K >= N - 1:
        raise ValueError("Invalid input parameters")

    # Convert the number string into a list of integers
    num_list = [int(digit) for digit in num_str]

    # If K is 0, the entire number is a single product
    if K == 0:
        return int(''.join(map(str, num_list)))

    # Insert K multiplication signs in all possible positions
    max_product = 0
    from itertools import combinations
    possible_positions = list(combinations(range(1, N), K))

    for positions in possible_positions:
        current_product = 1
        last_position = 0
        for pos in positions:
            current_product *= int(''.join(map(str, num_list[last_position:pos])))
            last_position = pos
        current_product *= int(''.join(map(str, num_list[last_position:])))
        if current_product > max_product:
            max_product = current_product

    return max_product

