def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    # Step 1: Initialize counters for rows and columns
    row_counter = [0] * M
    col_counter = [0] * N

    # Step 2: Count the number of chatting pairs that can be separated by adding an aisle in each possible row and column
    for pair in chatting_pairs:
        if pair[0] == pair[2]:
            col_counter[pair[1] - 1] += 1
            col_counter[pair[3]] += 1
        elif pair[1] == pair[3]:
            row_counter[pair[0] - 1] += 1
            row_counter[pair[2]] += 1

    # Step 3: Sort the row and column counters
    row_counter.sort(reverse=True)
    col_counter.sort(reverse=True)

    # Step 4: Select the most effective positions for aisles
    optimal_rows = []
    optimal_cols = []

    for _ in range(K):
        if row_counter and row_counter[0] > 0:
            optimal_rows.append(str(row_counter.index(row_counter[0]) + 1))
            row_counter[row_counter.index(row_counter[0])] = 0

    for _ in range(L):
        if col_counter and col_counter[0] > 0:
            optimal_cols.append(str(col_counter.index(col_counter[0]) + 1))
            col_counter[col_counter.index(col_counter[0])] = 0

    # Step 5: Return the optimal row and column indices for the aisles
    return (''.join(optimal_rows), ' '.join(optimal_cols))

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("Invalid input: n must be a positive integer and m must be a non-negative integer.")
    if n == 1:
        return 1 if m == 0 else 0
    dp = [[0] * (m + 1) for _ in range(n)]
    dp[0][1] = 1
    dp[0][0] = 1
    for i in range(1, n):
        dp[i][0] = 1
        dp[i][1] = i
    for j in range(2, m + 1):
        dp[0][j] = dp[0][j - 1] + dp[1][j - 1]
        for i in range(1, n):
            dp[i][j] = dp[i - 1][j - 1] + dp[i][j - 1] + dp[(i + 1) % n][j - 1]
    return dp[0][m]

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("n must be positive and m must be non-negative")
    if n == 1:
        return 1
    if m == 0:
        return 1

    dp = [[0] * (m + 1) for _ in range(n)]
    dp[0][0] = 1

    for i in range(1, n):
        dp[i][0] = 1

    for j in range(1, m + 1):
        dp[0][j] = dp[1][j - 1]
        for i in range(1, n):
            dp[i][j] = (dp[i - 1][j - 1] + dp[i + 1][j - 1]) % 1000000007

    return dp[0][m]

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("Invalid input: n should be greater than 0 and m should be non-negative.")

    if m == 0:
        return 1

    # Initialize dp array where dp[i][j] represents the number of ways to pass the ball to the i-th student after j passes
    dp = [[0] * (m + 1) for _ in range(n)]

    # Base case: There is one way to be at each student after 0 passes
    for i in range(n):
        dp[i][0] = 1

    # Fill the dp array
    for j in range(1, m + 1):
        for i in range(n):
            dp[i][j] = dp[(i - 1) % n][j - 1] + dp[(i + 1) % n][j - 1]

    # The result is the number of ways to be at the starting student after m passes
    return dp[0][m]

def count_passing_ways(n: int, m: int) -> int:
    if n <= 1 or m < 0:
        return 0

    # Initialize a 2D array to store the number of ways to pass the ball to each student after a certain number of passes
    dp = [[0] * (m + 1) for _ in range(n)]

    # There's only one way to pass the ball 0 times to any student
    for i in range(n):
        dp[i][0] = 1

    # Fill the dp array
    for j in range(1, m + 1):
        dp[0][j] = dp[n - 1][j - 1]
        dp[n - 1][j] = dp[0][j - 1]
        for i in range(1, n - 1):
            dp[i][j] = dp[i - 1][j - 1] + dp[i + 1][j - 1]

    # The number of ways to return to the starting student after m passes
    return dp[0][m]

