def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Sort items by price to use a greedy approach
    items.sort()

    max_impact = 0
    current_budget = n

    # Iterate through sorted items and add them to the budget if possible
    for price, impact in items:
        if price <= current_budget:
            max_impact += impact
            current_budget -= price
        else:
            break

    return max_impact

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Create a 2D list to store the maximum importance values
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Iterate over each item
    for i in range(1, m + 1):
        price, importance = items[i - 1]
        # Iterate over each possible budget
        for j in range(n + 1):
            # If the current budget is less than the item's price, take the previous maximum value
            if j < price:
                dp[i][j] = dp[i - 1][j]
            else:
                # Otherwise, choose the maximum between not taking the item or taking the item
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - price] + importance)

    # The answer is the maximum importance value with the given budget
    return dp[m][n]

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a list to store the maximum importance value for each budget
    dp = [0] * (n + 1)

    # Iterate over each item
    for price, importance in items:
        # Update the dp array from the back to the front to avoid using the same item multiple times
        for budget in range(n, price - 1, -1):
            dp[budget] = max(dp[budget], dp[budget - price] + importance)

    # The maximum importance value is the last element in the dp array
    return dp[n]

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
