    dp = [0] * (n + 1)

    # Iterate over each item
    for price, importance in items:
        # Update the DP array from back to front to avoid using the same item multiple times
        for budget in range(n, price - 1, -1):
            dp[budget] = max(dp[budget], dp[budget - price] + importance)

    # The maximum importance value that can be achieved with the given budget is the last element in the DP array
    return dp[n]

def max_energy(beads):
    n = len(beads)
    if n < 3:
        return 0

    # Create a circular array to handle the circular nature of the necklace
    beads = beads + beads

    # Initialize a DP table
    dp = [[0] * n for _ in range(n)]

    # Fill the DP table
    for length in range(2, n + 1):
        for i in range(n):
            j = i + length - 1
            if j >= 2 * n:
                break
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    return dp[0][n - 1]

def max_energy(beads):
