    dp = [[0] * n for _ in range(n)]

    for length in range(1, n):
        for start in range(n - length):
            end = (start + length) % n
            for k in range(start, end):
                dp[start][end] = max(dp[start][end], dp[start][k] + dp[(k + 1) % n][end] + beads[start] * beads[k + 1] * beads[end])

    return dp[0][(n - 1) % n]

def max_energy(beads):
    n = len(beads)
    if n < 3:
        return 0

    # Convert beads list to a circular list by appending the first element at the end
    beads += [beads[0]]

    # Create a 2D DP table where dp[i][j] represents the maximum energy obtainable
    # by merging beads from position i to j (j is exclusive)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Fill the DP table
    for length in range(2, n + 1):
        for i in range(1, n - length + 2):
            j = i + length - 1
            for k in range(i, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k + 1][j] + beads[i - 1] * beads[k] * beads[j])

    return dp[1][n]

def max_energy(beads):
