    applicants.sort(key=lambda x: (-x[1], x[0]))

    # Calculate the cutoff index based on 150% of the planned number of recruits, rounded down
    cutoff_index = max(0, int(m * 1.5) - 1)

    # Determine the interview score cutoff
    if cutoff_index < len(applicants):
        cutoff_score = applicants[cutoff_index][1]
    else:
        cutoff_score = applicants[-1][1]

    # Select qualified applicants
    qualified_applicants = [app for app in applicants if app[1] >= cutoff_score]

    return cutoff_score, qualified_applicants

