def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Check if the number of herbs exceeds the list length
    if M != len(herbs):
        raise ValueError("The number of herbs provided does not match the length of the herbs list.")

    # Initialize a DP array to store the maximum value for each possible time
    dp = [0] * (T + 1)

    # Iterate over each herb
    for t, v in herbs:
        # Update the DP array from right to left to avoid using the same herb multiple times
        for time in range(T, t - 1, -1):
            dp[time] = max(dp[time], dp[time - t] + v)

    # The maximum value we can pick without exceeding the time limit T
    return dp[-1]

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Check for invalid inputs
    if T < 0 or M < 0 or not herbs:
        raise ValueError("Invalid input values")

    # Sort herbs by time cost to ensure we always consider the smallest time first
    herbs.sort()

    # Initialize a 2D list to store the maximum value for each time limit
    dp = [[0] * (M + 1) for _ in range(T + 1)]

    # Fill the DP table
    for t in range(1, T + 1):
        for m in range(1, M + 1):
            time, value = herbs[m - 1]
            if time <= t:
                # Include the current herb or exclude it
                dp[t][m] = max(dp[t][m - 1], dp[t - time][m - 1] + value)
            else:
                # Exclude the current herb
                dp[t][m] = dp[t][m - 1]

    return dp[T][M]

