        for j in range(i+1, n):
            if heights[i] > heights[j]:
                decreasing[i] = max(decreasing[i], decreasing[j] + 1)

    # Find the maximum length of the valid choir formation
    max_choir_length = 0
    for i in range(n):
        max_choir_length = max(max_choir_length, increasing[i] + decreasing[i] - 1)

    # The minimum number of students to leave is the total number of students minus the maximum choir length
    return n - max_choir_length

def minimum_students_to_leave(heights):
