        return 0
    return 2 * (2 ** n) - 2

def hanoi_double_iterative(n: int) -> int:
    if n < 1:
        raise ValueError("The number of disc pairs must be a positive integer.")

    # The minimum number of moves for the double-disc Hanoi Towers problem is given by the formula: 2^n - 2
    return 2 ** n - 2

def hanoi_double_iterative(n: int) -> int:
    if n < 1:
        raise ValueError("The number of disc pairs must be at least 1")

    # The recursive relation for the double-disc Hanoi Towers problem is:
    # T(1) = 2
    # T(n) = 3*T(n-1) + 2
    moves = 2
    for _ in range(2, n + 1):
        moves = 3 * moves + 2

    return moves
